def insert(trie, word):
    node = trie
    for ch in word:
        node = node.setdefault(ch, {})
    node["$"] = True
def count(node):
    return sum(1 if k == "$" else count(v) for k, v in node.items())
def count_prefix(trie, prefix):
    node = trie
    for ch in prefix:
        if ch not in node:
            return 0
        node = node[ch]
    return count(node)
